.nl-input { min-height: 90px; margin-bottom: 10px; }
.nl-item.ask { border-color: var(--amber); } .ask-q { color: var(--amber); font-weight: 650; font-size: 14px; } .nl-item .row-b { margin: 8px 0 4px; } .nl-item .chips { margin: 6px 0; }
