.wave { position: absolute; top: -10px; left: -50%; width: 200%; height: 20px; background: radial-gradient(circle at 10px -4px, transparent 12px, var(--sky) 13px) 0 0/30px 20px repeat-x; animation: wave 2.5s linear infinite; }
@keyframes wave { to { transform: translateX(30px); } }
.glass-t { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; text-shadow: 0 2px 8px rgba(0, 0, 0, .4); } .glass-t b { font-size: 26px; font-weight: 850; } .glass-t small { color: var(--text); }
