.pf img, .pf video { width: 100%; height: 100%; object-fit: cover; } .pf button { position: absolute; top: 4px; right: 4px; width: 22px; height: 22px; border-radius: 11px; background: rgba(0, 0, 0, .6); color: #fff; display: grid; place-items: center; }
