.prof-h { display: flex; gap: 16px; align-items: center; } .prof-n { display: flex; flex-direction: column; gap: 4px; align-items: flex-start; } .prof-n b { font-size: 19px; } .prof-n p { margin: 0; color: var(--text-2); font-size: 14px; }
