.dlg-bg { align-items: center; padding: 24px; z-index: 300; } .dlg { background: var(--bg-2); border: 1px solid var(--line); border-radius: 22px; padding: 20px; width: 100%; max-width: 380px; display: flex; flex-direction: column; gap: 14px; animation: pop .2s; }
.dlg p { margin: 0; font-size: 15.5px; font-weight: 600; } .dlg-a { display: flex; justify-content: flex-end; gap: 8px; }
.day-pick { display: grid; grid-template-columns: repeat(5, 1fr); gap: 8px; } .day-pick button { height: 52px; border-radius: 16px; background: var(--card); border: 1.5px solid var(--line); font-weight: 800; font-size: 18px; } .day-pick button.on { border-color: var(--lime); background: rgba(198, 255, 61, .1); color: var(--lime); }
.quick { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; } .quick button { background: var(--card); border: 1px solid var(--line); border-radius: 18px; padding: 12px 4px; display: flex; flex-direction: column; align-items: center; gap: 6px; font-size: 12px; font-weight: 700; color: var(--text-2); }
.quick button span { width: 44px; height: 44px; border-radius: 14px; display: grid; place-items: center; background: rgba(198, 255, 61, .12); color: var(--lime); } .quick button:active { transform: scale(.95); }
.checklist { border-color: var(--lime-dim); background: linear-gradient(135deg, rgba(198, 255, 61, .08), transparent 60%), var(--card); }
.checklist h3 { font-size: 17px; } .check-item { display: flex; align-items: center; gap: 12px; width: 100%; text-align: left; padding: 10px 0; border-bottom: 1px solid var(--line); font-weight: 600; font-size: 14.5px; }
.check-item:last-child { border-bottom: 0; } .check-item i { width: 24px; height: 24px; border-radius: 50%; border: 2px solid var(--line); display: grid; place-items: center; font-style: normal; font-size: 13px; flex-shrink: 0; }
.check-item.done { color: var(--text-3); text-decoration: line-through; } .check-item.done i { background: var(--lime); border-color: var(--lime); color: var(--lime-ink); } .check-item em { margin-left: auto; font-style: normal; color: var(--lime); font-size: 13px; }
.yt { width: 100%; display: flex; flex-direction: column; gap: 8px; } .yt-thumb { position: relative; width: 100%; aspect-ratio: 16/9; border-radius: 16px; overflow: hidden; background: #000; display: block; }
.yt-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; } .yt-ph { width: 100%; height: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; background: radial-gradient(circle at 30% 30%, rgba(198,255,61,.25), transparent 60%), #111; color: #fff; }
.yt-play { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: 66px; height: 66px; border-radius: 50%; background: rgba(198, 255, 61, .92); color: #0B0F02; display: grid; place-items: center; box-shadow: 0 8px 30px rgba(0,0,0,.5); padding-left: 4px; }
.yt-badge { position: absolute; left: 10px; bottom: 10px; background: rgba(0,0,0,.7); color: #fff; font-size: 12px; font-weight: 700; padding: 4px 10px; border-radius: 999px; }
.yt-frame { width: 100%; aspect-ratio: 16/9; border: 0; border-radius: 16px; background: #000; } .yt-foot { display: flex; justify-content: space-between; align-items: center; gap: 8px; } .yt-foot small { font-size: 11.5px; color: var(--text-3); } .yt-foot a { font-size: 13px; font-weight: 700; }
.demo { align-items: stretch; }
:root, [data-theme='dark'] { --mm-off-a: #4a3438; --mm-off-b: #3a2a2e; --mm-skin-a: #2b3038; --mm-skin-b: #22262d; --mm-line: #0f1216; --mm-hair: #000; }
[data-theme='light'] { --mm-off-a: #e7b9b4; --mm-off-b: #d39d97; --mm-skin-a: #efe2d6; --mm-skin-b: #e2d2c3; --mm-line: #fff; --mm-hair: #6b5b4b; }
.mm-legend { gap: 18px; font-size: 13px; }
.times-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 4px 0 8px; } .times-grid label { display: flex; flex-direction: column; gap: 4px; } .times-grid input { width: 100% !important; padding: 10px 6px; font-size: 14px; }
/* 3D muscle model */
.m3d { display: flex; flex-direction: column; gap: 10px; align-items: stretch; }
.m3d-stage { position: relative; width: 100%; height: 440px; border-radius: 18px; overflow: hidden; background: radial-gradient(120% 80% at 50% 30%, #2a2f38 0%, #14171c 55%, #0b0d10 100%); border: 1px solid var(--line, #232830); }
[data-theme="light"] .m3d-stage { background: radial-gradient(120% 80% at 50% 30%, #ffffff 0%, #e9ecf1 60%, #d9dde4 100%); }
.m3d-canvas, .m3d-canvas canvas { position: absolute; inset: 0; width: 100% !important; height: 100% !important; display: block; }
.m3d-over { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; text-align: center; padding: 24px; color: var(--text-1, #fff); background: rgba(10,12,15,.35); }
.m3d-over small { color: var(--text-2); max-width: 260px; }
.m3d-ring { width: 54px; height: 54px; border-radius: 50%; background: conic-gradient(#D8261B calc(var(--p) * 1%), rgba(255,255,255,.12) 0); -webkit-mask: radial-gradient(circle 20px, transparent 98%, #000 100%); mask: radial-gradient(circle 20px, transparent 98%, #000 100%); animation: m3dspin 1.6s linear infinite; }
@keyframes m3dspin { to { transform: rotate(360deg); } }
.m3d-pick { position: absolute; left: 50%; top: 12px; transform: translateX(-50%); background: rgba(0,0,0,.72); color: #fff; padding: 7px 14px; border-radius: 999px; font-size: 13px; font-weight: 600; white-space: nowrap; max-width: 92%; overflow: hidden; text-overflow: ellipsis; backdrop-filter: blur(6px); }
.m3d-hint { position: absolute; bottom: 8px; left: 0; right: 0; text-align: center; font-size: 11px; color: rgba(255,255,255,.55); pointer-events: none; }
[data-theme="light"] .m3d-hint { color: rgba(0,0,0,.45); }
.m3d-bar { display: flex; gap: 6px; flex-wrap: wrap; } .m3d-bar.center { justify-content: center; margin-top: 8px; }
.m3d-credit { color: var(--text-3); font-size: 10.5px; text-align: center; }
.m3d .mm-legend { justify-content: center; flex-wrap: wrap; }
/* one-tap sign in */
.join-card { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 8px; padding: 20px 18px; border-radius: 20px; background: linear-gradient(160deg, rgba(198,255,61,.10), rgba(34,227,181,.06)); border: 1px solid var(--line); margin: 6px 0 12px; }
.join-card b { font-size: 17px; } .join-card p { color: var(--text-2); font-size: 14px; margin: 0 0 4px; line-height: 1.45; }
.join-ico { font-size: 30px; }
.join-btns { display: flex; flex-direction: column; gap: 10px; width: 100%; }
.join-btns > button { display: flex; align-items: center; justify-content: center; gap: 10px; height: 52px; border-radius: 16px; font-weight: 700; font-size: 15px; width: 100%; }
.g-btn { background: #fff; color: #1f1f1f; border: 1px solid #dadce0; }
.e-btn { background: var(--card); color: var(--text-1); border: 1px solid var(--line); }
input.otp { letter-spacing: .5em; font-size: 24px; text-align: center; font-weight: 700; }
button.link { background: none; border: 0; color: var(--accent, #C6FF3D); font-weight: 600; padding: 4px 6px; }
/* chat */
.inbox-row { display: flex; align-items: center; gap: 12px; padding: 12px 4px; border-bottom: 1px solid var(--line); cursor: pointer; }
.inbox-row > div:not(.avatar) { flex: 1; min-width: 0; } .inbox-row b { display: block; } .inbox-row small { color: var(--text-2); display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.inbox-row .when { color: var(--text-3); font-size: 12px; flex: none; text-align: right; } .inbox-row .dot { display: inline-block; min-width: 20px; height: 20px; border-radius: 10px; background: #C6FF3D; color: #000; font-size: 11px; font-weight: 800; line-height: 20px; text-align: center; margin-top: 4px; padding: 0 5px; }
.chat { display: flex; flex-direction: column; height: 100%; min-height: calc(100vh - 70px); min-height: calc(100dvh - 70px); }
.chat-msgs { flex: 1; overflow-y: auto; display: flex; flex-direction: column; gap: 6px; padding: 10px 2px 90px; }
.bubble { max-width: 78%; padding: 9px 13px; border-radius: 18px; font-size: 15px; line-height: 1.35; white-space: pre-wrap; word-wrap: break-word; }
.bubble.me { align-self: flex-end; background: #C6FF3D; color: #0b0d10; border-bottom-right-radius: 6px; }
.bubble.them { align-self: flex-start; background: var(--card); border: 1px solid var(--line); border-bottom-left-radius: 6px; }
.bubble.pending { opacity: .55; } .bubble small { display: block; font-size: 10.5px; opacity: .6; margin-top: 3px; text-align: right; }
.chat-day { align-self: center; font-size: 11.5px; color: var(--text-3); margin: 8px 0 2px; }
.chat-box { position: fixed; left: 0; right: 0; bottom: 0; display: flex; gap: 8px; padding: 10px 12px calc(10px + env(safe-area-inset-bottom)); background: var(--bg, #0A0C0F); border-top: 1px solid var(--line); max-width: 640px; margin: 0 auto; }
.chat-box textarea { flex: 1; resize: none; min-height: 44px; max-height: 120px; border-radius: 22px; padding: 11px 16px; background: var(--card); border: 1px solid var(--line); color: var(--text-1); font: inherit; }
.chat-box button { width: 46px; height: 46px; border-radius: 50%; background: #C6FF3D; color: #000; border: 0; display: flex; align-items: center; justify-content: center; flex: none; }
.chat-box button:disabled { opacity: .4; }
.quick-replies { display: flex; gap: 6px; overflow-x: auto; padding: 0 0 6px; } .quick-replies button { flex: none; }
.join-link { display: flex; align-items: center; justify-content: center; height: 50px; border-radius: 16px; font-weight: 700; width: 100%; text-decoration: none; }
.invite-hero { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 10px; }
.invite-hero b { font-size: 18px; } .invite-hero p { margin: 0 0 4px; }
.invite-link { display: flex; align-items: center; gap: 8px; background: var(--bg, #0A0C0F); border: 1px solid var(--line); border-radius: 12px; padding: 8px 10px; }
.invite-link code { flex: 1; font-size: 11.5px; word-break: break-all; color: var(--text-2); }
.invite-link button { background: none; border: 0; color: var(--text-1); padding: 6px; }
/* sports */
.sport-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.sport-grid button { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 14px 6px; border-radius: 18px; background: var(--card); border: 1px solid var(--line); color: var(--text-1); }
.sport-grid span { font-size: 30px; } .sport-grid small { font-size: 12.5px; text-align: center; line-height: 1.2; }
.sport-head { display: flex; align-items: center; gap: 14px; } .sport-emo { font-size: 44px; } .sport-head b { font-size: 26px; display: block; } .sport-head small { color: var(--text-2); }
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.lvl-list { display: flex; flex-direction: column; gap: 8px; } .lvl-list button { display: flex; justify-content: space-between; align-items: center; padding: 12px 14px; border-radius: 14px; border: 1px solid var(--line); background: var(--bg-2, transparent); color: var(--text-1); text-align: left; }
.lvl-list button.on { border-color: #C6FF3D; background: rgba(198,255,61,.1); } .lvl-list small { color: var(--text-2); }
.burn-top { display: flex; align-items: baseline; justify-content: space-between; margin: 4px 0 8px; } .burn-top em { font-size: 14px; font-style: normal; color: var(--text-2); }
.burn-list { display: flex; flex-direction: column; gap: 6px; margin-bottom: 8px; } .burn-list div { display: flex; justify-content: space-between; gap: 8px; font-size: 14px; } .burn-list small { color: var(--text-2); white-space: nowrap; }
.sport-quick { display: flex; gap: 6px; justify-content: space-between; } .sport-quick button { flex: 1; display: flex; flex-direction: column; align-items: center; font-size: 22px; padding: 8px 0; border-radius: 14px; background: var(--bg-2, rgba(255,255,255,.04)); border: 1px solid var(--line); color: var(--text-1); } .sport-quick small { font-size: 10.5px; color: var(--text-2); }
/* friends leaderboard */
.board .seg { margin: 6px 0 8px; }
.board-row { display: flex; align-items: center; gap: 10px; padding: 7px 4px; border-radius: 12px; }
.board-row.me { background: rgba(198,255,61,.08); }
.board-row .rank { width: 24px; text-align: center; font-weight: 800; color: var(--text-2); }
.board-mid { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; } .board-mid b { font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.board-mid i { display: block; height: 5px; border-radius: 3px; background: linear-gradient(90deg, #C6FF3D, #22E3B5); }
.board-val { font-weight: 800; font-size: 15px; white-space: nowrap; } .board-val small { font-weight: 500; color: var(--text-2); font-size: 11px; } .board-val .streak { color: #FFB020; }
/* status row */
.status-row { display: flex; gap: 12px; padding: 4px 2px 10px; overflow-x: auto; }
.status { display: flex; flex-direction: column; align-items: center; gap: 5px; background: none; border: 0; color: var(--text-1); flex: none; width: 68px; }
.status small { font-size: 11.5px; max-width: 68px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-2); }
.status .ring { position: relative; padding: 3px; border-radius: 50%; background: var(--line); }
.status .ring.new { background: conic-gradient(#C6FF3D, #22E3B5, #4FC3F7, #C6FF3D); }
.status .ring .avatar { border: 2px solid var(--bg, #0A0C0F); }
.status .ring.add i { position: absolute; right: 0; bottom: 0; width: 20px; height: 20px; border-radius: 50%; background: #C6FF3D; color: #000; font-style: normal; font-weight: 900; line-height: 19px; text-align: center; border: 2px solid var(--bg, #0A0C0F); }
.status-empty { padding: 18px 4px; }
/* story viewer */
.sv { position: fixed; inset: 0; z-index: 200; background: #000; display: flex; flex-direction: column; user-select: none; -webkit-user-select: none; }
.sv-bars { display: flex; gap: 4px; padding: calc(10px + env(safe-area-inset-top)) 10px 6px; } .sv-bars i { flex: 1; height: 3px; border-radius: 2px; background: rgba(255,255,255,.3); overflow: hidden; } .sv-bars b { display: block; height: 100%; background: #fff; }
.sv-top { display: flex; align-items: center; gap: 10px; padding: 4px 12px 10px; color: #fff; z-index: 2; } 
.sv-top > div:not(.avatar) { flex: 1; } .sv-top b { display: block; } .sv-top small { opacity: .7; } .sv-top button { background: none; border: 0; color: #fff; padding: 6px; z-index: 3; }
.sv-body { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; position: relative; overflow: hidden; }
.sv-media { max-width: 100%; max-height: 100%; object-fit: contain; }
.sv-text { color: #fff; font-size: 26px; font-weight: 700; text-align: center; padding: 30px; line-height: 1.3; white-space: pre-wrap; }
.sv-cap { position: absolute; bottom: 70px; left: 0; right: 0; color: #fff; text-align: center; padding: 12px 18px; background: linear-gradient(transparent, rgba(0,0,0,.7)); white-space: pre-wrap; }
.sv-wo { color: #fff; text-align: center; font-size: 18px; padding: 14px 20px; background: rgba(255,255,255,.12); border-radius: 16px; margin: 10px; }
.sv-nav { position: absolute; top: 90px; bottom: 80px; width: 35%; background: none; border: 0; z-index: 1; } .sv-nav.l { left: 0; } .sv-nav.r { right: 0; }
.sv-open { position: absolute; bottom: calc(18px + env(safe-area-inset-bottom)); left: 50%; transform: translateX(-50%); background: rgba(255,255,255,.15); color: #fff; border: 1px solid rgba(255,255,255,.3); border-radius: 999px; padding: 10px 18px; font-weight: 600; z-index: 2; white-space: nowrap; }
.watch-help { display: flex; flex-direction: column; gap: 8px; margin-top: 6px; } .watch-help div { display: flex; flex-direction: column; } .watch-help small { color: var(--text-2); }
.board-mid .sync { font-size: 10.5px; color: var(--text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
